def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    N = 100000
    tests = [fmt([1]), fmt([5, 5, 5]), fmt([3, 1, 2]), fmt([-5, -5, 3, 3]), fmt([10 ** 9, -10 ** 9, 10 ** 9]), fmt([0, 0, 0, 1, 1, 2])]
    for n in (2, 4, 7, 10, 15, 25, 40):
        for _ in range(3):
            hi = rng.choice([2, 4, 10, 10 ** 9])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10 ** 9, 10 ** 9) for _ in range(N)]))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(N)]))
    tests.append(fmt([rng.randint(-300, 300) for _ in range(N)]))
    tests.append(fmt([7] * N))
    tests.append(fmt(rng.sample(range(-10 ** 9, 10 ** 9), N)))
    return tests
